1151:     // Web Audio Synthesizer: Play MIDI notes
1152:     function playMelodyNotes(notes, tempo, onEndedCallback) {
1153:         initAudioContext();
1154:         stopSynth();
1155: 
1156:         let time = audioContext.currentTime;
1157:         const beatDuration = 60 / tempo; // duration in seconds of 1 beat
1158:         
1159:         // For Santa Lucia, notes are based on 8th notes, so scale duration
1160:         const durationScale = (currentSongId === "sl") ? 0.5 : 1.0; 
1161: 
1162:         notes.forEach((note, idx) => {
1163:             const freq = 440 * Math.pow(2, (note.midi - 69) / 12);
1164:             const osc = audioContext.createOscillator();
1165:             const gainNode = audioContext.createGain();
1166:             
1167:             // Triangle wave creates a warm woodwind/flute-like tone
1168:             osc.type = 'triangle';
1169:             osc.frequency.setValueAtTime(freq, time);
1170:             
1171:             const dur = note.duration * beatDuration * durationScale;
1172:             
1173:             // Gain envelope to prevent clicking
1174:             gainNode.gain.setValueAtTime(0, time);
1175:             gainNode.gain.linearRampToValueAtTime(0.2, time + 0.05); // Attack
1176:             gainNode.gain.setValueAtTime(0.2, time + dur - 0.03);
1177:             gainNode.gain.exponentialRampToValueAtTime(0.0001, time + dur); // Decay/Release
1178:             
1179:             osc.connect(gainNode);
1180:             gainNode.connect(audioContext.destination);
1181:             
1182:             osc.start(time);
1183:             osc.stop(time + dur);
1184:             
1185:             activeOscillators.push(osc);
1186:             time += dur;
1187:         });
1188: 
1189:         // Trigger callback when the whole note sequence ends
1190:         const totalDuration = notes.reduce((acc, note) => acc + (note.duration * beatDuration * durationScale), 0);
1191:         repeatTimer = setTimeout(() => {
1192:             if (onEndedCallback) onEndedCallback();
1193:         }, totalDuration * 1000);
1194:     }
