// Browser native TTS reading
function speakLine(text, lang, onEndCallback) {
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = lang || "en-US";
    utterance.rate = 0.8; // Slow reading rate

    utterance.onend = () => {
        if (onEndCallback) onEndCallback();
    };
    utterance.onerror = (e) => {
        console.error("SpeechSynthesis error:", e);
        if (onEndCallback) onEndCallback();
    };

    window.speechSynthesis.speak(utterance);
}

// Play single line voice (manual click)
function playSingleVoice(index, event) {
    event.stopPropagation();
    stopPractice();

    highlightCard(index, 'voice');
    updateStatus(`正在朗讀第 ${index + 1} 句...`, true);
    speakLine(songs[currentSongId].lines[index].text, songs[currentSongId].lang, () => {
        if (!isPracticeMode) {
            setTimeout(dehighlightAll, 300);
        }
    });
}

