import urllib.request

def main():
    url = "https://raw.githubusercontent.com/chenlili-a/song-learning-assistant/main/index.html"
    try:
        with urllib.request.urlopen(url) as response:
            html = response.read().decode('utf-8')

        sg_idx = html.find("sg: {")
        if sg_idx != -1:
            notes_idx = html.find("notes:", sg_idx)
            print("SG Line 1 Notes:")
            print(html[notes_idx:notes_idx+150])

            sl_idx = html.find("sl: {")
            if sl_idx != -1:
                notes_idx_sl = html.find("notes:", sl_idx)
                print("SL Line 1 Notes:")
                print(html[notes_idx_sl:notes_idx_sl+150])
        else:
            print("sg block not found!")
    except Exception as e:
        print(f"Error fetching URL: {e}")

if __name__ == "__main__":
    main()
